  },
  {
    "kind": "dialogue",
    "speaker_id": "c804a210-3087-4ffe-80fd-5890e817f011",
    "text": "\"Stalls open at second bell.\"",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "cited_fact_keys": ["attempt:wait"],
    "text": "Ash waits patiently."
  },
  {
    "kind": "action",
    "cited_fact_keys": ["attempt:communicate"],
