[
  {
    "kind": "narration",
    "text": "Marlow and Wren huddle together, attempting to communicate with Ash.",
    "cited_fact_keys": ["attempt:communicate", "attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash waits patiently for their message.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "beb03d24-74c7-467d-9cc3-744e2a9f83bf",
    "text": "Aye, and mind the loose stones past the bridge.",
    "cited_fact_keys": ["reaction:1"]
  },
  {
    "kind": "narration",
    "text": "Ash acknowledges their warning.",
    "cited_fact_keys": ["reaction:1"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "fe1afce1-2f18-4100-9a4b-28b70af800a8",
    "text": "Dawn bell means the first stalls are opening.",
    "cited_fact_keys": ["reaction:2"]
  },
  {
    "kind": "narration",
    "text": "Wren nods, understanding the significance of the dawn bell.",
    "cited_fact_keys": ["reaction:2"]
  },
  {
    "kind": "narration",
    "text": "The group prepares to move out, the road ahead clear.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash leads the way, ready for the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  }
]

[
  {
    "kind": "narration",
    "text": "Ash waits patiently, his gaze fixed on the horizon.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Wren tries to engage Ash in conversation about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Marlow watches the scene unfold, taking it all in.",
    "cited_fact_keys": ["attempt:observe"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "0bba4d24-88b9-4543-8d77-f7117260225f",
    "text": "Dawn bell means the market's waking.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking about their journey ahead.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash, meanwhile, waits patiently for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"Dawn bell means the market is waking early today, so hurry down with coin and basket before the best bread and freshest fish are gone from the stalls.\"",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "5f0d1e47-a6f4-4cf2-83bd-4b54d5d0be60"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren tries to engage Ash in conversation, seeking to know if the old bridge is safe to cross.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash remains silent, waiting for Wren to continue.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "17f37dc2-cf4c-4730-b0b8-d13bdf28dd44",
    "text": "\"No.\" Ash responds curtly to Wren's inquiry.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'What news from the mill, Ash?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "4b135b1c-48da-4a54-bdb2-5743b141d486",
    "text": "'It's still standing, unless someone's moved it.' Ash replies to Wren.",
    "cited_fact_keys": ["reaction:1"]
  }
]
